import assert from 'node:assert/strict';import {createHmac} from 'node:crypto';import {writeFileSync} from 'node:fs';
let serial=0;async function raw(sid,object,method,args={}){let r=await fetch('http://192.168.10.1/ubus',{method:'POST',headers:{'Content-Type':'application/json',Connection:'close'},signal:AbortSignal.timeout(30000),body:JSON.stringify({jsonrpc:'2.0',id:++serial,method:'call',params:[sid,object,method,args]})});let b=await r.json();assert.equal(b.result?.[0],0,'RPC_ACCESS_FAILED');return b.result[1]||{};}async function call(s,o,m,a){let r=await raw(s,o,m,a);assert(!r.error,r.error);return r;}
const sid=(await call('0'.repeat(32),'session','login',{username:'root',password:'',timeout:300})).ubus_rpc_session;
async function preview(content){let bytes=Buffer.from(content),up=await call(sid,'gale-backup','upload_begin',{bytes:bytes.length});for(let offset=0;offset<bytes.length;offset+=up.chunk_bytes)await call(sid,'gale-backup','upload_chunk',{token:up.token,offset,data:bytes.subarray(offset,offset+up.chunk_bytes).toString('base64')});return raw(sid,'gale-backup','upload_finish',{token:up.token});}
try{
 const exported=await call(sid,'gale-backup','export_full'),key=await call(sid,'gale-backup','export_key');writeFileSync('.private/full-recovery-acceptance.json',exported.content);writeFileSync('.private/full-recovery-key.txt',key.content);
 const good=await preview(exported.content);assert(!good.error,good.error);assert.equal(good.kind,'full');
 if(process.argv.includes('--refresh-only')){writeFileSync('.private/full-recovery-preview.json',JSON.stringify(good));console.log({fresh_signed_bundle:true,bytes:Buffer.byteLength(exported.content),code_version:good.code_version});process.exit(0);}
 let envelope=JSON.parse(exported.content),payload=JSON.parse(envelope.payload);payload.created_at++;envelope.payload=JSON.stringify(payload);const tampered=await preview(JSON.stringify(envelope));assert.equal(tampered.error,'RECOVERY_SIGNATURE_REJECTED');
 envelope=JSON.parse(exported.content);payload=JSON.parse(envelope.payload);payload.device.firmware='other-firmware';envelope.payload=JSON.stringify(payload);envelope.signature=createHmac('sha256',Buffer.from(key.content,'base64')).update(envelope.payload).digest('hex');const wrong=await preview(JSON.stringify(envelope));assert.equal(wrong.error,'RECOVERY_DEVICE_OR_FIRMWARE_MISMATCH');
 const restoredPreview=await preview(exported.content);assert(!restoredPreview.error,restoredPreview.error);writeFileSync('.private/full-recovery-preview.json',JSON.stringify(restoredPreview));
 const result={signed_full_bundle:true,bytes:Buffer.byteLength(exported.content),profiles:good.profiles,sources:good.sources,code_included:true,host_identity_included:true,six_system_configs_validated:true,tampered_signature_rejected:true,foreign_firmware_rejected:true,physical_LAN_changed:false};writeFileSync('docs/recovery-bundle-result.json',JSON.stringify(result,null,2));console.log(result);
}finally{await call(sid,'session','destroy');}
